Given an integer array arr[] and an integer k, partition the array into contiguous subarrays such that each subarray has a length of at most k. After partitioning, replace every element in each subarray with the maximum element present in that subarray. Compute the maximum possible sum of the array after performing this operation.Input: arr = [4, 1, 2, 3], k = 2Output: 14Explanation: One optimal partition is [4, 1] and [2, 3]. Therefore, the maximum possible sum will be 4 + 4 + 3 + 3 = 14.Input: arr[] = [2, 2], k = 1Output: 4Explanation: The array is partitioned as [2] and [2]. Hence, the sum is 2 + 2 = 4.Input: arr[] = [4, 6, 1, 1, 1], k = 2Output: 18Explanation: One optimal partition is [4], [6, 1] and [1, 1], Therefore, the maximum possible sum will be 4 + 6 + 6 + 1 + 1 = 18.Try It YourselfTable of Content[Naive Approach] - Using Recursion - O(k^n) Time and O(n) Space[Expected Approach] - Using Dynamic Programming – O(n^2) Time and O(n) Space[Naive Approach] - Using Recursion - O(k^n) Time and O(n) SpaceThe idea is to try all possible partitions starting from the current index. For each partition of length from 1 to k, we keep track of the maximum element in that partition. Since every element in the partition is replaced by this maximum value, its contribution becomes maximum element × partition length. We then recursively solve the remaining array and take the maximum sum among all possible partition choices. 
            C++

    #include<iostream>
#include<vector>
using namespace std;

// Returns the maximum sum obtainable starting from index i
int maxSumRec(vector<int>& arr, int i, int k) {
    int n = arr.size();

    // No elements left to partition
    if (i == n)
        return 0;

    int maxVal = 0;
    int ans = 0;

    // Try all valid partition lengths starting at i
    for (int j = i; j < min(n, i + k); j++) {
        maxVal = max(maxVal, arr[j]);

        int len = j - i + 1;
        ans = max(ans, maxVal * len + maxSumRec(arr, j + 1, k));
    }

    return ans;
}

// Returns the maximum possible sum after partitioning arr[]
int maxPartitionSum(vector<int>& arr, int k) {
    return maxSumRec(arr, 0, k);
}

int main() {
    vector<int> arr = {4, 1, 2, 3};
    int k = 2;

    cout << maxPartitionSum(arr, k) << endl;
    return 0;
}


